import sqlite3, json

try:
    conn = sqlite3.connect('/workspace/world.db')
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()

    results = {}

    cursor.execute("SELECT name FROM sqlite_master WHERE type='table'")
    tables = [row['name'] for row in cursor.fetchall()]
    results['tables'] = tables

    table_info = {}
    for t in tables:
        cursor.execute(f"PRAGMA table_info({t})")
        cols = [(row['name'], row['type']) for row in cursor.fetchall()]
        cursor.execute(f"SELECT COUNT(*) FROM {t}")
        count = cursor.fetchone()[0]
        table_info[t] = {'columns': cols, 'row_count': count}
    results['table_info'] = table_info

    matches = []
    for t in tables:
        cursor.execute(f"PRAGMA table_info({t})")
        cols = cursor.fetchall()
        for col in cols:
            col_name = col['name']
            try:
                cursor.execute(f"SELECT * FROM {t} WHERE CAST({col_name} AS TEXT) LIKE '%E0E671%'")
                rows = cursor.fetchall()
                if rows:
                    matches.append({'table': t, 'column': col_name, 'rows': [dict(r) for r in rows]})
            except Exception:
                pass
    results['order_search'] = matches

    product_matches = []
    for t in tables:
        cursor.execute(f"PRAGMA table_info({t})")
        cols = cursor.fetchall()
        for col in cols:
            col_name = col['name']
            try:
                cursor.execute(f"SELECT * FROM {t} WHERE CAST({col_name} AS TEXT) LIKE '%Aurora%' OR CAST({col_name} AS TEXT) LIKE '%Lamp%'")
                rows = cursor.fetchall()
                if rows:
                    product_matches.append({'table': t, 'column': col_name, 'count': len(rows), 'sample': [dict(r) for r in rows[:2]]})
            except Exception:
                pass
    results['product_search'] = product_matches

    samples = {}
    for t in tables[:5]:
        cursor.execute(f"SELECT * FROM {t} LIMIT 2")
        rows = cursor.fetchall()
        samples[t] = [dict(r) for r in rows]
    results['samples'] = samples

    conn.close()

    with open('/workspace/db_output.json', 'w') as f:
        json.dump(results, f, indent=2, default=str)

except Exception as e:
    with open('/workspace/db_output.json', 'w') as f:
        json.dump({'error': str(e), 'type': type(e).__name__}, f)
